// FV 2.0 Self-Hosting: Parser를 FV 언어로 재작성
// 목표: FV를 FV로 파싱

// ============= AST 노드 =============

struct Program {
	mut definitions: []Definition
	mut main_body: []Statement
}

struct Definition {
	mut kind: string
	mut name: string
	mut data: ?string
}

struct Statement {
	mut kind: string
	mut content: ?string
}

