// TestOptionType tests Option[T] type handling
func TestOptionType(t *testing.T) {
	checker := New()

	program := &ast.Program{
		Definitions: []ast.Definition{},
		MainBody: []ast.Statement{
			&ast.LetStatement{
				Name: "maybe_val",
				Type: &ast.Type{
					Name:     "Option",
					IsOption: true,
					ElementType: &ast.Type{Name: "i64"},
				},
				Init: &ast.NoneLiteral{},
			},
		},
	}

	errors, _ := checker.Check(program)
	if len(errors) != 0 {
		t.Fatalf("expected 0 errors for valid Option type, got %d: %v", len(errors), errors)
	}
}

// TestResultType tests Result[T, E] type handling
func TestResultType(t *testing.T) {
