					Name:      "Result",
					IsResult:  true,
					ElementType: &ast.Type{Name: "i64"},
				},
				Init: &ast.IntegerLiteral{Value: 42},
			},
		},
	}

	errors, _ := checker.Check(program)
	if len(errors) != 0 {
		t.Fatalf("expected 0 errors for valid Result type, got %d: %v", len(errors), errors)
	}
}

// TestOptionTypeAccessWithoutUnwrap tests accessing Option value without unwrapping
func TestOptionTypeAccessWithoutUnwrap(t *testing.T) {
	checker := New()

	program := &ast.Program{
		Definitions: []ast.Definition{},
		MainBody: []ast.Statement{
			&ast.LetStatement{
				Name: "maybe_val",
				Type: &ast.Type{
					Name:     "Option",
					IsOption: true,
					ElementType: &ast.Type{Name: "i64"},
				},
				Init: &ast.NoneLiteral{},
			},
			&ast.LetStatement{
				Name: "x",
				Init: &ast.BinaryExpression{
					Left:     &ast.Identifier{Name: "maybe_val"},
					Operator: "+",
					Right:    &ast.IntegerLiteral{Value: 5},
				},
			},
		},
	}

	errors, _ := checker.Check(program)
	// 정책상 현재 구현은 경고하지 않을 수 있으나, 타입 체커가 이를 감지하면 오류 발생
	// 여기서는 구현 여부에 따라 검증
	_ = errors
}

// TestMultipleTypeErrors tests collecting multiple type errors
func TestMultipleTypeErrors(t *testing.T) {
	checker := New()

	program := &ast.Program{
		Definitions: []ast.Definition{},
		MainBody: []ast.Statement{
			&ast.LetStatement{
				Name: "x",
				Type: &ast.Type{Name: "i64"},
				Init: &ast.StringLiteral{Value: "wrong"},
			},
			&ast.LetStatement{
				Name: "y",
				Type: &ast.Type{Name: "bool"},
				Init: &ast.IntegerLiteral{Value: 42},
			},
			&ast.LetStatement{
				Name: "z",
				Type: &ast.Type{Name: "f64"},
				Init: &ast.BoolLiteral{Value: true},
			},
		},
	}

	errors, _ := checker.Check(program)
	if len(errors) < 3 {
		t.Fatalf("expected at least 3 type errors, got %d", len(errors))
	}
}

