     1→#!/usr/bin/env ts-node
     2→
     3→import * as fs from 'fs';
     4→import * as path from 'path';
     5→import { PyFreeLexer } from './lexer';
     6→import { PyFreeParser } from './parser';
     7→import { IRCompiler } from './runtime/ir';
     8→import { VM } from './runtime/vm';
     9→
    10→const args = process.argv.slice(2);
    11→
    12→if (args.length === 0) {
    13→  console.log('Usage: pyfree <file.pf>');
    14→  process.exit(1);
    15→}
    16→
    17→const filePath = args[0];
    18→
    19→try {
    20→  // 파일 읽기
    21→  const source = fs.readFileSync(filePath, 'utf-8');
    22→
    23→  // 렉싱
    24→  const lexer = new PyFreeLexer(source);
    25→  const tokens = lexer.tokenize();
    26→
    27→  // 파싱
    28→  const parser = new PyFreeParser(tokens);
    29→  const ast = parser.parse();
    30→
    31→  // IR 컴파일
    32→  const compiler = new IRCompiler();
    33→  const irProgram = compiler.compile(ast);
    34→
    35→  // ✅ Phase 15: baseDir 전달
    36→  const baseDir = path.dirname(path.resolve(filePath));
    37→  const vm = new VM(irProgram, baseDir);
    38→  vm.execute();
    39→
    40→  const output = vm.getOutput();
    41→  if (output) {
    42→    console.log(output);
    43→  }
    44→} catch (error: any) {
    45→  console.error('Error:', error.message);
    46→  process.exit(1);
    47→}
