    11→
    12→import { IRProgram, Instruction, Opcode, IRFunction } from './ir';
    13→import { ModuleResolver } from './module-resolver';
    14→
    15→/**
    16→ * 런타임 값
    17→ */
    18→export type PyFreeValue = any;
    19→
    20→/**
    21→ * 호출 프레임
    22→ */
    23→interface Frame {
    24→  function?: IRFunction;
    25→  code: Instruction[];
    26→  pc: number;  // Program Counter
    27→  registers: PyFreeValue[];
    28→  locals: Map<string, PyFreeValue>;
    29→  returnValue?: PyFreeValue;
    30→  returnResultReg?: number;        // 반환값 저장할 호출자 레지스터
    31→  callerRegisters?: PyFreeValue[]; // 호출자 레지스터 배열 참조
    32→  closureEnv?: Map<string, PyFreeValue>; // ✅ Phase 10: 클로저 환경
    33→  moduleGlobals?: Map<string, any>; // ✅ Phase 15.5: 모듈의 전역 상태
    34→}
    35→
    36→/**
    37→ * 루프 컨텍스트
    38→ */
    39→interface LoopContext {
    40→  startOffset: number;
    41→  endOffset: number;
    42→}
    43→
    44→/**
    45→ * 예외 핸들러
    46→ */
    47→interface ExceptionHandler {
    48→  offset: number;
    49→  endOffset?: number;
    50→}
    51→
    52→/**
    53→ * PyFree VM
    54→ */
    55→export class VM {
    56→  private program: IRProgram;
    57→  private registers: PyFreeValue[] = new Array(256);
    58→  private frameStack: Frame[] = [];
    59→  private loopStack: LoopContext[] = [];
    60→  private handlerStack: ExceptionHandler[] = [];
    61→  private globals: Map<string, PyFreeValue> = new Map();
    62→  private output: string[] = [];
    63→  private halted: boolean = false;
    64→  private baseDir: string;  // ✅ Phase 15
    65→  private moduleResolver: ModuleResolver;  // ✅ Phase 15
    66→  private sharedGlobals?: Map<string, any>;  // ✅ Phase 15.5: 모듈 공유 전역 상태
    67→  private sharedModuleResolver?: ModuleResolver;  // ✅ Phase 15.5: 순환 임포트 감지용
    68→
    69→  constructor(program: IRProgram, baseDir?: string, sharedGlobals?: Map<string, any>, sharedModuleResolver?: ModuleResolver) {
    70→    this.program = program;
    71→    this.baseDir = baseDir || process.cwd();
    72→    this.sharedGlobals = sharedGlobals;  // ✅ Phase 15.5
    73→    this.sharedModuleResolver = sharedModuleResolver;  // ✅ Phase 15.5
    74→
    75→    // ModuleResolver 공유 또는 새로 생성
    76→    if (this.sharedModuleResolver) {
    77→      this.moduleResolver = this.sharedModuleResolver;
    78→    } else {
    79→      this.moduleResolver = new ModuleResolver(this.baseDir);
    80→      // ✅ Phase 15: 모듈 로더 등록
    81→      this.moduleResolver.setLoader((source: string, filePath: string) => {
    82→        return this.createModuleLoader(source, filePath);
    83→      });
    84→    }
    85→
    86→    // ✅ Phase 15.5: sharedGlobals 또는 독립 globals 선택
    87→    if (this.sharedGlobals) {
    88→      this.globals = this.sharedGlobals;
    89→    }
    90→    // 항상 program globals와 native library 추가 (sharedGlobals 포함)
    91→    this.program.globals.forEach((value, key) => {
    92→      this.globals.set(key, value);
    93→    });
    94→
    95→    // 네이티브 라이브러리 함수 등록 (항상)
    96→    Object.entries(NativeLibrary).forEach(([name, fn]) => {
    97→      if (!this.globals.has(name)) {  // 이미 있으면 덮어쓰지 않음
    98→        this.globals.set(name, fn);
    99→      }
   100→    });

