    36→
    37→/**
    38→ * 스코프 (변수 범위)
    39→ */
    40→interface Scope {
    41→  parent?: Scope;
    42→  symbols: Map<string, Symbol>;
    43→}
    44→
    45→/**
    46→ * 타입 체커
    47→ */
    48→export class TypeChecker {
    49→  private program: AST.Program;
    50→  private level: 0 | 1 | 2 = 1;
    51→  private globalScope: Scope;
    52→  private currentScope: Scope;
    53→  private errors: TypeCheckError[] = [];
    54→  private functionStack: string[] = [];
    55→
    56→  constructor(program: AST.Program, level: 0 | 1 | 2 = 1) {
    57→    this.program = program;
    58→    this.level = level;
    59→    this.globalScope = { symbols: new Map() };
    60→    this.currentScope = this.globalScope;
    61→  }
    62→
    63→  /**
    64→   * 타입 체크 수행
    65→   */
    66→  check(): TypeCheckError[] {
    67→    this.errors = [];
    68→    this.checkProgram(this.program);
    69→    return this.errors;
    70→  }
    71→
    72→  /**
    73→   * 프로그램 체크
    74→   */
    75→  private checkProgram(program: AST.Program): void {
    76→    for (const stmt of program.body) {
    77→      this.checkStatement(stmt);
    78→    }
    79→  }
