    40→  private baseDir: string = process.cwd();
    41→  private loader?: ModuleLoader;  // ✅ Phase 15: 모듈 로더
    42→  private moduleGlobals: Map<string, Map<string, any>> = new Map();  // ✅ Phase 15.5: 모듈 전역 상태 공유
    43→
    44→  constructor(baseDir?: string) {
    45→    if (baseDir) {
    46→      this.baseDir = baseDir;
