     9→
    10→const args = process.argv.slice(2);
    11→
    12→if (args.length === 0) {
    13→  console.log('Usage: pyfree <file.pf>');
    14→  process.exit(1);
    15→}
    16→
    17→const filePath = args[0];
    18→
    19→try {
    20→  // 파일 읽기
    21→  const source = fs.readFileSync(filePath, 'utf-8');
    22→
    23→  // 렉싱
