    33→  const irProgram = compiler.compile(ast);
    34→
    35→  // ✅ Phase 15: baseDir 전달
    36→  const baseDir = path.dirname(path.resolve(filePath));
    37→  const vm = new VM(irProgram, baseDir);
    38→  vm.execute();
    39→
    40→  const output = vm.getOutput();
    41→  if (output) {
    42→    console.log(output);
    43→  }
