     2→
     3→/**
     4→ * PyFree 패키지 관리자 CLI
     5→ * Phase 4-2: 패키지 관리자
     6→ *
     7→ * 명령어:
     8→ * - pyfree init [project-name]
     9→ * - pyfree install [package]
    10→ * - pyfree build
    11→ * - pyfree test
    12→ * - pyfree run [script]
    13→ * - pyfree publish
    14→ */
    15→
    16→import { PackageConfigParser, PackageConfig } from './package-config';
    17→import { PackageCache } from './package-cache';
    18→import { defaultRegistry } from './registry';
    19→import fs from 'fs';
    20→import path from 'path';
    21→
    22→/**
    23→ * PyFree 패키지 관리자
    24→ */
    25→class PyFreePkg {
    26→  private projectRoot: string;
    27→  private config?: PackageConfig;
    28→  private cache: PackageCache;
    29→
    30→  constructor() {
    31→    this.projectRoot = process.cwd();
    32→    this.cache = new PackageCache();
    33→  }
    34→
    35→  /**
    36→   * 메인 진입점
    37→   */
    38→  async run(args: string[]): Promise<void> {
    39→    const command = args[0];
    40→
    41→    try {
    42→      switch (command) {
    43→        case 'init':
    44→          await this.handleInit(args.slice(1));
    45→          break;
    46→
    47→        case 'install':
    48→        case 'i':
    49→          await this.handleInstall(args.slice(1));
    50→          break;
    51→
    52→        case 'build':
    53→          await this.handleBuild(args.slice(1));
    54→          break;
    55→
    56→        case 'test':
    57→          await this.handleTest(args.slice(1));
    58→          break;
    59→
    60→        case 'run':
    61→          await this.handleRun(args.slice(1));
    62→          break;
    63→
    64→        case 'publish':
    65→          await this.handlePublish(args.slice(1));
    66→          break;
    67→
    68→        case 'cache':
    69→          await this.handleCache(args.slice(1));
    70→          break;
    71→
    72→        case '--version':
    73→        case '-v':
    74→          this.printVersion();
    75→          break;
    76→
    77→        case '--help':
    78→        case '-h':
    79→        default:
    80→          this.printHelp();
    81→          break;
    82→      }
    83→    } catch (error) {
    84→      console.error('❌ 오류:', error instanceof Error ? error.message : error);
    85→      process.exit(1);
    86→    }
    87→  }
    88→
    89→  /**
    90→   * init 명령어 - 새 프로젝트 초기화
    91→   */
    92→  private async handleInit(args: string[]): Promise<void> {
    93→    const projectName = args[0] || 'pyfree-project';
    94→    const projectPath = path.join(this.projectRoot, projectName);
    95→
    96→    if (fs.existsSync(projectPath)) {
    97→      throw new Error(`디렉토리가 이미 존재함: ${projectPath}`);
    98→    }
    99→
   100→    // 디렉토리 생성
   101→    fs.mkdirSync(projectPath, { recursive: true });
   102→
   103→    // pyfree.json 생성
   104→    const config = PackageConfigParser.createDefault(projectName);
   105→    PackageConfigParser.saveConfig(config, projectPath);
   106→
   107→    // src 디렉토리 생성
   108→    const srcDir = path.join(projectPath, 'src');
   109→    fs.mkdirSync(srcDir, { recursive: true });
   110→
   111→    // main.pf 생성
   112→    const mainPf = path.join(srcDir, 'main.pf');
   113→    fs.writeFileSync(
   114→      mainPf,
   115→      `# PyFree 프로젝트: ${projectName}\n\nfn main() -> str {
   116→  "Hello, PyFree!"
   117→}\n`
   118→    );
   119→
   120→    // .gitignore 생성
   121→    const gitIgnore = path.join(projectPath, '.gitignore');
   122→    fs.writeFileSync(
   123→      gitIgnore,
   124→      `dist/
   125→node_modules/
   126→*.pyo
   127→.DS_Store
   128→`
   129→    );
   130→
   131→    // README 생성
   132→    const readme = path.join(projectPath, 'README.md');
   133→    fs.writeFileSync(
   134→      readme,
   135→      `# ${projectName}
   136→
   137→PyFree 프로젝트
   138→
   139→## 빌드
   140→
   141→\`\`\`bash
   142→pyfree build
   143→\`\`\`
   144→
   145→## 실행
   146→
   147→\`\`\`bash
   148→pyfree run
   149→\`\`\`
   150→
   151→## 테스트
   152→
   153→\`\`\`bash
   154→pyfree test
   155→\`\`\`
   156→`
   157→    );
   158→
   159→    console.log(`✅ 프로젝트 생성됨: ${projectPath}`);
   160→  }
   161→
   162→  /**
   163→   * install 명령어 - 패키지 설치
   164→   */
   165→  private async handleInstall(args: string[]): Promise<void> {
   166→    if (args.length === 0) {
   167→      // pyfree.json 기반 설치
   168→      this.loadConfig();
   169→
   170→      if (!this.config) {
   171→        throw new Error('pyfree.json을 찾을 수 없습니다');
   172→      }
   173→
   174→      const deps = { ...this.config.dependencies };
   175→
   176→      for (const [name, version] of Object.entries(deps)) {
   177→        console.log(`📦 설치중: ${name}@${version}`);
   178→
   179→        // 실제 설치 로직
   180→        // - 레지스트리에서 메타데이터 조회
   181→        // - 캐시 확인
   182→        // - 없으면 다운로드
   183→        // - 캐시에 저장
   184→
   185→        const metadata = await defaultRegistry.getPackageInfo(name);
