## 🔬 **첫 테스트 케이스 (구체적)**

```typescript
describe('NexusLexer - Phase 1', () => {

  test('V 모드: fn 키워드 인식', () => {
    const lexer = new NexusLexer();
    const tokens = lexer.tokenize('@mode(v)\nfn hello() {}');

    expect(tokens[0].type).toBe(TokenType.MODE_MARKER);
    expect(tokens[1].type).toBe(TokenType.FN);
    expect(tokens[1].mode).toBe('v');
  });

  test('Python 모드: def 키워드 인식', () => {
    const lexer = new NexusLexer();
    const tokens = lexer.tokenize('@mode(python)\ndef hello():');

    expect(tokens[0].type).toBe(TokenType.MODE_MARKER);
    expect(tokens[1].type).toBe(TokenType.DEF);
    expect(tokens[1].mode).toBe('python');
  });

  test('혼합 모드: V와 Python 함께', () => {
    const code = `
      @mode(v)
      fn fast() -> i64 { return 1 }

      @mode(python)
      def slow():
        return 2
    `;
    const tokens = lexer.tokenize(code);

    const vTokens = tokens.filter(t => t.mode === 'v');
    const pyTokens = tokens.filter(t => t.mode === 'python');

    expect(vTokens.length).toBeGreaterThan(0);
    expect(pyTokens.length).toBeGreaterThan(0);
  });

  test('Python 모드: INDENT/DEDENT 토큰', () => {
    const code = `
      @mode(python)
      def process():
        x = 1
        y = 2
      return x + y
    `;
    const tokens = lexer.tokenize(code);

    const indents = tokens.filter(t => 
      t.type === TokenType.INDENT || t.type === TokenType.DEDENT
    );
    expect(indents.length).toBeGreaterThan(0);
  });

  test('타입 표기: V 모드 @type', () => {
    const tokens = lexer.tokenize('@mode(v)\nfn calc(x: i64) -> i64');
    const typeToken = tokens.find(t => t.type === TokenType.COLON_TYPE);

    expect(typeToken).toBeDefined();
    expect(typeToken.mode).toBe('v');
  });
});
```

