/**
 * FreeLang Nexus - 통합 Lexer
 * V 모드 + Python 모드를 동시에 지원
 *
 * PyFree의 INDENT/DEDENT 패턴 + FV의 복합 연산자 처리 + 모드 전환
 */

import {
  Token,
  TokenType,
  getKeywordToken,
  detectMode,
  V_KEYWORDS,
  PYTHON_KEYWORDS,
} from './token';
import { ModeDetector } from './mode-detector';

export class NexusLexer {
  private source: string;
  private pos: number = 0;
  private line: number = 1;
  private column: number = 1;
  private currentMode: 'v' | 'python' | 'auto' = 'auto';
  private indentStack: number[] = [0]; // Python INDENT/DEDENT 스택 (PyFree 패턴)
  private atLineStart: boolean = true; // Python 들여쓰기 처리용
  private tokens: Token[] = [];

  constructor(source: string) {
    this.source = source;
  }

  /**
   * 전체 소스 토큰화
   */
  tokenize(): Token[] {
    while (this.pos < this.source.length) {
      this.skipWhitespaceOnLineStart();

      if (this.pos >= this.source.length) break;

      const token = this.nextToken();
      if (token) {
        this.tokens.push(token);
      }
    }

    // EOF 토큰 추가
    this.tokens.push(this.makeToken(TokenType.EOF, '', this.currentMode));

    return this.tokens;
  }

  /**
   * 다음 토큰 가져오기
   */
  private nextToken(): Token | null {
    const ch = this.peek();

    if (ch === undefined) {
      return null;
    }

    // 줄 시작에서 들여쓰기 처리 (Python 모드)
    if (this.atLineStart && this.currentMode === 'python') {
      if (ch !== '\n' && !this.isWhitespace(ch)) {
        this.atLineStart = false;
        const indentTokens = this.handleIndentation();
        if (indentTokens) {
          return indentTokens;
        }
      }
    }

    // 개행
    if (ch === '\n') {
      this.advance();
      this.atLineStart = true;
      return this.makeToken(TokenType.NEWLINE, '\n', this.currentMode);
    }

    // 공백 (탭, 스페이스)
    if (this.isWhitespace(ch)) {
      this.skipWhitespace();
      return this.nextToken(); // 재귀 호출
    }

    // 주석: V 모드는 //, Python 모드는 #
    if (ch === '/' && this.peek(1) === '/' && this.currentMode === 'v') {
      this.skipLineComment();
      return this.nextToken(); // 재귀 호출
    }

    if (ch === '#' && this.currentMode === 'python') {
      this.skipLineComment();
      return this.nextToken(); // 재귀 호출
    }

    // @mode 디렉티브
    if (ch === '@') {
      const modeToken = this.tryParseMode();
      if (modeToken) {
        return modeToken;
      }
    }

    // 문자열
    if (ch === '"' || ch === "'" || (ch === 'f' && (this.peek(1) === '"' || this.peek(1) === "'"))) {
      return this.tokenizeString();
    }

    // 숫자
    if (this.isDigit(ch)) {
      return this.tokenizeNumber();
    }

    // 식별자 또는 키워드
    if (this.isIdentifierStart(ch)) {
      return this.tokenizeIdentifierOrKeyword();
    }

    // 연산자
    const operatorToken = this.tokenizeOperator();
    if (operatorToken) {
      return operatorToken;
    }

    // 알 수 없는 문자
    throw new Error(`Unknown character: '${ch}' at line ${this.line}, column ${this.column}`);
  }

  /**
   * 들여쓰기 처리 (Python 모드 전용)
   * PyFree 패턴 재사용
   */
  private handleIndentation(): Token | null {
    let indent = 0;

    // 연속된 스페이스/탭 세기
    while (this.pos < this.source.length) {
      const ch = this.peek();
      if (ch === ' ') {
        indent += 1;
        this.advance();
      } else if (ch === '\t') {
        indent += 8; // 탭 = 8 스페이스
        this.advance();
      } else {
        break;
      }
    }

    const currentIndent = this.indentStack[this.indentStack.length - 1];

    if (indent > currentIndent) {
      // INDENT
      this.indentStack.push(indent);
      return this.makeToken(TokenType.INDENT, '\t', this.currentMode);
    } else if (indent < currentIndent) {
      // DEDENT (여러 개 가능)
      while (this.indentStack.length > 0 && this.indentStack[this.indentStack.length - 1] > indent) {
        this.indentStack.pop();
      }
      return this.makeToken(TokenType.DEDENT, '', this.currentMode);
    }

    return null;
  }

  /**
   * 식별자 또는 키워드 토큰화
   */
  private tokenizeIdentifierOrKeyword(): Token {
    const start = this.pos;
    const startColumn = this.column;

    while (this.pos < this.source.length && this.isIdentifierChar(this.peek())) {
      this.advance();
    }

    const value = this.source.substring(start, this.pos);

    // 키워드 확인
    const keywordType = getKeywordToken(value, this.currentMode);
    if (keywordType) {
      return this.makeToken(keywordType, value, this.currentMode);
    }

    return this.makeToken(TokenType.IDENTIFIER, value, this.currentMode);
  }

  /**
   * 숫자 토큰화
   */
  private tokenizeNumber(): Token {
    const start = this.pos;

    // 16진수 (0x)
    if (this.peek() === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
      this.advance(); // '0'
      this.advance(); // 'x'
      while (this.isHexDigit(this.peek())) {
        this.advance();
      }
    }
    // 2진수 (0b)
    else if (this.peek() === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      this.advance(); // '0'
      this.advance(); // 'b'
      while (this.peek() === '0' || this.peek() === '1') {
        this.advance();
      }
    }
    // 8진수 (0o)
    else if (this.peek() === '0' && (this.peek(1) === 'o' || this.peek(1) === 'O')) {
      this.advance(); // '0'
      this.advance(); // 'o'
      while (this.isOctalDigit(this.peek())) {
        this.advance();
      }
    }
    // 10진수 (정수 또는 실수)
    else {
      while (this.isDigit(this.peek())) {
        this.advance();
      }

      // 실수: . 또는 e/E
      if (this.peek() === '.' && this.isDigit(this.peek(1))) {
        this.advance(); // '.'
        while (this.isDigit(this.peek())) {
          this.advance();
        }
      }

      if (this.peek() === 'e' || this.peek() === 'E') {
        this.advance();
        if (this.peek() === '+' || this.peek() === '-') {
          this.advance();
        }
        while (this.isDigit(this.peek())) {
          this.advance();
        }
      }
    }

    const value = this.source.substring(start, this.pos);
    return this.makeToken(TokenType.NUMBER, value, this.currentMode);
  }

  /**
   * 문자열 토큰화
   */
  private tokenizeString(): Token {
    const start = this.pos;
    let isFString = false;

    // f-string 확인
    if (this.peek() === 'f' && (this.peek(1) === '"' || this.peek(1) === "'")) {
      isFString = true;
      this.advance(); // 'f'
    }

    const quote = this.peek();
    this.advance(); // 첫 따옴표

    // 3중 따옴표 확인
    let isTriple = false;
    if (this.peek() === quote && this.peek(1) === quote) {
      isTriple = true;
      this.advance();
      this.advance();
    }

    // 문자열 내용 읽기
    while (this.pos < this.source.length) {
      const ch = this.peek();

      if (isTriple) {
        if (ch === quote && this.peek(1) === quote && this.peek(2) === quote) {
          this.advance();
          this.advance();
          this.advance();
          break;
        }
      } else {
        if (ch === quote) {
          this.advance();
          break;
        }
        if (ch === '\n') {
          throw new Error(`Unterminated string at line ${this.line}`);
        }
      }

      if (ch === '\\') {
        this.advance(); // 이스케이프 문자 다음
        if (this.pos < this.source.length) {
          this.advance();
        }
      } else {
        this.advance();
      }
    }

    const value = this.source.substring(start, this.pos);
    return this.makeToken(TokenType.STRING, value, this.currentMode);
  }

  /**
   * 연산자 토큰화
   */
  private tokenizeOperator(): Token | null {
    const ch = this.peek();
    const next = this.peek(1);
    const next2 = this.peek(2);

    // 3글자 연산자
    if (ch === '.' && next === '.' && next2 === '=') {
      this.advance();
      this.advance();
      this.advance();
      return this.makeToken(TokenType.IDENTIFIER, '..=', this.currentMode); // 커스텀
    }

    // 2글자 연산자
    const twoChar = ch + (next || '');
    const twoCharMap: Record<string, TokenType> = {
      '->': TokenType.ARROW,
      '=>': TokenType.IDENTIFIER, // FatArrow (커스텀)
      '==': TokenType.EQ,
      '!=': TokenType.NE,
      '<=': TokenType.LE,
      '>=': TokenType.GE,
      '&&': TokenType.AND,
      '||': TokenType.OR,
      '::': TokenType.IDENTIFIER, // DoubleColon (커스텀)
      '..': TokenType.IDENTIFIER, // DotDot (커스텀)
      '//': TokenType.SLASH, // 이미 주석 처리됨
      '**': TokenType.STAR, // Power (커스텀)
    };

    if (twoCharMap[twoChar]) {
      this.advance();
      this.advance();
      return this.makeToken(twoCharMap[twoChar], twoChar, this.currentMode);
    }

    // 1글자 연산자
    const oneCharMap: Record<string, TokenType> = {
      '(': TokenType.LPAREN,
      ')': TokenType.RPAREN,
      '{': TokenType.LBRACE,
      '}': TokenType.RBRACE,
      '[': TokenType.LBRACKET,
      ']': TokenType.RBRACKET,
      ',': TokenType.COMMA,
      '.': TokenType.DOT,
      ';': TokenType.SEMICOLON,
      ':': TokenType.COLON,
      '=': TokenType.EQUAL,
      '+': TokenType.PLUS,
      '-': TokenType.MINUS,
      '*': TokenType.STAR,
      '/': TokenType.SLASH,
      '%': TokenType.PERCENT,
      '<': TokenType.LT,
      '>': TokenType.GT,
      '!': TokenType.NOT,
      '&': TokenType.AMPERSAND,
      '|': TokenType.PIPE,
      '@': TokenType.AT,
    };

    if (oneCharMap[ch]) {
      this.advance();
      return this.makeToken(oneCharMap[ch], ch, this.currentMode);
    }

    return null;
  }

  /**
   * @mode() 디렉티브 파싱
   */
  private tryParseMode(): Token | null {
    const start = this.pos;

    if (this.peek() !== '@') {
      return null;
    }

    this.advance(); // '@'

    // @mode 확인
    if (
      this.peek() === 'm' &&
      this.peek(1) === 'o' &&
      this.peek(2) === 'd' &&
      this.peek(3) === 'e'
    ) {
      this.advance();
      this.advance();
      this.advance();
      this.advance();

      // 공백 및 ( 확인
      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
        this.advance();
      }

      if (this.peek() !== '(') {
        // @mode가 아니면 다시 돌아가기
        this.pos = start;
        return null;
      }

      this.advance(); // '('

      // 공백
      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
        this.advance();
      }

      // v 또는 python 확인
      let mode: 'v' | 'python' | null = null;

      if (this.peek() === 'v' && (this.peek(1) === ')' || this.isWhitespace(this.peek(1)))) {
        mode = 'v';
        this.advance();
      } else if (
        this.peek() === 'p' &&
        this.peek(1) === 'y' &&
        this.peek(2) === 't' &&
        this.peek(3) === 'h' &&
        this.peek(4) === 'o' &&
        this.peek(5) === 'n'
      ) {
        mode = 'python';
        this.advance();
        this.advance();
        this.advance();
        this.advance();
        this.advance();
        this.advance();
      }

      if (!mode) {
        // 유효한 모드가 아니면 다시 돌아가기
        this.pos = start;
        return null;
      }

      // 공백 및 ) 확인
      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
        this.advance();
      }

      if (this.peek() !== ')') {
        this.pos = start;
        return null;
      }

      this.advance(); // ')'

      // 모드 전환!
      this.currentMode = mode;

      const value = this.source.substring(start, this.pos);
