/**
 * FreeLang Nexus Lexer - 단위 테스트
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { TokenType } from '../src/nexus/lexer/token';

describe('NexusLexer - Phase 1 핵심 테스트', () => {
  // ==================== Test 1: V 모드 ====================
  test('V 모드: fn 키워드 인식', () => {
    const source = `@mode(v)
fn hello() {
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // @mode(v) 찾기
    const modeToken = tokens.find((t) => t.type === TokenType.MODE_MARKER);
    expect(modeToken).toBeDefined();
    expect(modeToken?.value).toMatch(/@mode\(v\)/);
    expect(modeToken?.mode).toBe('v');

    // fn 키워드 찾기
    const fnToken = tokens.find((t) => t.type === TokenType.FN);
    expect(fnToken).toBeDefined();
    expect(fnToken?.mode).toBe('v');
  });

  test('V 모드: 타입 표기 처리', () => {
    const source = `@mode(v)
fn calc(x: i64) -> i64 {
  return x * 2
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // i64 타입 확인
    const i64Token = tokens.find((t) => t.value === 'i64');
    expect(i64Token).toBeDefined();
    expect(i64Token?.mode).toBe('v');

    // -> 화살표 확인
    const arrowToken = tokens.find((t) => t.type === TokenType.ARROW);
    expect(arrowToken).toBeDefined();
    expect(arrowToken?.value).toBe('->');
  });

  // ==================== Test 2: Python 모드 ====================
  test('Python 모드: def 키워드 인식', () => {
    const source = `@mode(python)
def hello():
  print("hello")`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // @mode(python) 찾기
    const modeToken = tokens.find((t) => t.type === TokenType.MODE_MARKER);
    expect(modeToken).toBeDefined();
    expect(modeToken?.value).toMatch(/@mode\(python\)/);
    expect(modeToken?.mode).toBe('python');

    // def 키워드 찾기
    const defToken = tokens.find((t) => t.type === TokenType.DEF);
    expect(defToken).toBeDefined();
    expect(defToken?.mode).toBe('python');
  });

  test('Python 모드: 문자열 인식', () => {
    const source = `@mode(python)
message = "hello world"`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // 문자열 찾기
    const stringToken = tokens.find((t) => t.type === TokenType.STRING);
    expect(stringToken).toBeDefined();
    expect(stringToken?.value).toBe('"hello world"');
    expect(stringToken?.mode).toBe('python');
  });

  // ==================== Test 3: 혼합 모드 ====================
  test('혼합 모드: V + Python 함수 공존', () => {
    const source = `@mode(v)
fn fast(x: i64) -> i64 {
  return x * x
}

@mode(python)
def slow(items):
  return items

fn main():
  return fast(5)`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // V 모드 토큰 확인
    const vModeTokens = tokens.filter((t) => t.mode === 'v');
    const fnToken = vModeTokens.find((t) => t.type === TokenType.FN);
    expect(fnToken).toBeDefined();

    // Python 모드 토큰 확인
    const pyModeTokens = tokens.filter((t) => t.mode === 'python');
    const defToken = pyModeTokens.find((t) => t.type === TokenType.DEF);
    expect(defToken).toBeDefined();

    // 모드 전환 확인
    const modeTokens = tokens.filter((t) => t.type === TokenType.MODE_MARKER);
    expect(modeTokens.length).toBe(2);
  });

  // ==================== Test 4: Python INDENT/DEDENT ====================
  test('Python 모드: INDENT/DEDENT 토큰 생성', () => {
    const source = `@mode(python)
def process():
  x = 1
  y = 2
  if True:
    z = 3
  return x + y`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // INDENT 토큰 찾기
    const indentTokens = tokens.filter((t) => t.type === TokenType.INDENT);
    expect(indentTokens.length).toBeGreaterThan(0);

    // DEDENT 토큰 찾기
    const dedentTokens = tokens.filter((t) => t.type === TokenType.DEDENT);
    expect(dedentTokens.length).toBeGreaterThan(0);
  });

  // ==================== Test 5: 모드 전환 ====================
  test('모드 전환: @mode(v) → @mode(python)', () => {
    const source = `@mode(v)
fn fast() -> i64 { return 1 }

@mode(python)
def slow():
  return 2`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // V 섹션에서 fn 찾기
    let inVMode = false;
    let foundFn = false;

    for (const token of tokens) {
      if (token.type === TokenType.MODE_MARKER && token.mode === 'v') {
        inVMode = true;
      } else if (token.type === TokenType.MODE_MARKER && token.mode === 'python') {
        inVMode = false;
      } else if (inVMode && token.type === TokenType.FN) {
        foundFn = true;
      }
    }

    expect(foundFn).toBe(true);

    // Python 섹션에서 def 찾기
    let inPyMode = false;
    let foundDef = false;

    for (const token of tokens) {
      if (token.type === TokenType.MODE_MARKER && token.mode === 'python') {
        inPyMode = true;
      } else if (token.type === TokenType.MODE_MARKER && token.mode === 'v') {
        inPyMode = false;
      } else if (inPyMode && token.type === TokenType.DEF) {
        foundDef = true;
      }
    }

    expect(foundDef).toBe(true);
  });

  // ==================== 보너스 테스트 ====================
  test('숫자 토큰화: 10진수, 16진수, 2진수', () => {
    const source = `@mode(v)
let a = 123
let b = 0xFF
let c = 0b1010`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // 숫자 찾기
    const numbers = tokens.filter((t) => t.type === TokenType.NUMBER);
    expect(numbers.length).toBeGreaterThanOrEqual(3);
    expect(numbers[0]?.value).toBe('123');
    expect(numbers[1]?.value).toBe('0xFF');
    expect(numbers[2]?.value).toBe('0b1010');
  });

  test('연산자: ->, ::', () => {
    const source = `@mode(v)
fn test() -> i64 {
  Module::func()
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // -> 찾기
    const arrowToken = tokens.find((t) => t.value === '->');
    expect(arrowToken?.type).toBe(TokenType.ARROW);

    // :: 찾기
    const doubleColonToken = tokens.find((t) => t.value === '::');
    expect(doubleColonToken).toBeDefined();
  });

  test('주석 처리: V는 //, Python은 #', () => {
    const source = `@mode(v)
fn test() {
  // V 주석
}

@mode(python)
def test():
  # Python 주석
  pass`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // 주석이 토큰에 포함되지 않아야 함
    const commentTokens = tokens.filter((t) => t.value.includes('//') || t.value.includes('#'));
    expect(commentTokens.length).toBe(0);
  });
});

