        inVMode = true;
      } else if (token.type === TokenType.MODE_MARKER && token.mode === 'python') {
        inVMode = false;
      } else if (inVMode && token.type === TokenType.FN) {
        foundFn = true;
      }
    }

    expect(foundFn).toBe(true);

    // Python 섹션에서 def 찾기
    let inPyMode = false;
    let foundDef = false;

    for (const token of tokens) {
      if (token.type === TokenType.MODE_MARKER && token.mode === 'python') {
        inPyMode = true;
      } else if (token.type === TokenType.MODE_MARKER && token.mode === 'v') {
        inPyMode = false;
      } else if (inPyMode && token.type === TokenType.DEF) {
        foundDef = true;
      }
    }

    expect(foundDef).toBe(true);
  });

