        this.peek() === 'p' &&
        this.peek(1) === 'y' &&
        this.peek(2) === 't' &&
        this.peek(3) === 'h' &&
        this.peek(4) === 'o' &&
        this.peek(5) === 'n'
      ) {
        mode = 'python';
        this.advance();
        this.advance();
        this.advance();
        this.advance();
        this.advance();
        this.advance();
