        return null;
      }

      this.advance(); // '('

      // 공백
      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
        this.advance();
      }

      // v 또는 python 확인
      let mode: 'v' | 'python' | null = null;

      if (this.peek() === 'v' && (this.peek(1) === ')' || this.isWhitespace(this.peek(1)))) {
        mode = 'v';
        this.advance();
      } else if (
        this.peek() === 'p' &&
        this.peek(1) === 'y' &&
        this.peek(2) === 't' &&
        this.peek(3) === 'h' &&
        this.peek(4) === 'o' &&
        this.peek(5) === 'n'
      ) {
        mode = 'python';
        this.advance();
        this.advance();
        this.advance();
        this.advance();
        this.advance();
        this.advance();
      }

      if (!mode) {
        // 유효한 모드가 아니면 다시 돌아가기
        this.pos = start;
        return null;
      }

      // 공백 및 ) 확인
      while (this.isWhitespace(this.peek()) && this.peek() !== '\n') {
        this.advance();
      }

      if (this.peek() !== ')') {
        this.pos = start;
        return null;
      }

      this.advance(); // ')'

      // 모드 전환!
      this.currentMode = mode;

      const value = this.source.substring(start, this.pos);
      return this.makeToken(TokenType.MODE_MARKER, value, mode);
    }

    this.pos = start;
    return null;
  }

  // ==================== 헬퍼 함수 ====================

  private skipWhitespaceOnLineStart(): void {
    // 라인 시작의 공백 스킵
    while (this.pos < this.source.length) {
      const ch = this.peek();
      if (ch === ' ' || ch === '\t') {
        this.advance();
      } else if (ch === '\n') {
        this.advance();
        this.atLineStart = true;
      } else {
        break;
      }
    }
  }

  private skipWhitespace(): void {
    while (this.pos < this.source.length && this.isWhitespace(this.peek())) {
      this.advance();
    }
  }

  private skipLineComment(): void {
    while (this.pos < this.source.length && this.peek() !== '\n') {
      this.advance();
    }
  }

  private peek(offset: number = 0): string | undefined {
    return this.source[this.pos + offset];
  }

  private advance(): void {
    const ch = this.peek();
    if (ch === '\n') {
      this.line++;
      this.column = 1;
    } else {
      this.column++;
    }
    this.pos++;
  }

  private isWhitespace(ch: string | undefined): boolean {
    return ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n';
  }

  private isDigit(ch: string | undefined): boolean {
    return ch !== undefined && ch >= '0' && ch <= '9';
  }

  private isHexDigit(ch: string | undefined): boolean {
    return (
      ch !== undefined &&
      ((ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F'))
    );
  }

  private isOctalDigit(ch: string | undefined): boolean {
    return ch !== undefined && ch >= '0' && ch <= '7';
  }

  private isIdentifierStart(ch: string | undefined): boolean {
    return (
      ch !== undefined &&
      ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_' || ch === '$')
    );
  }

  private isIdentifierChar(ch: string | undefined): boolean {
    return this.isIdentifierStart(ch) || this.isDigit(ch);
  }

  private makeToken(
    type: TokenType,
    value: string,
    mode: 'v' | 'python' | 'auto'
  ): Token {
    return {
      type,
      value,
      line: this.line,
      column: this.column - value.length,
      mode,
      startPos: this.pos - value.length,
      endPos: this.pos,
    };
  }
}

