    30→// ==================== 문장 (Statements) ====================
    31→
    32→export type Statement =
    33→  | FunctionDef
    34→  | FreeLangFunction
    35→  | ClassDef
    36→  | IfStatement
    37→  | ForLoop
    38→  | WhileLoop
    39→  | TryStatement
    40→  | ReturnStatement
    41→  | BreakStatement
    42→  | ContinueStatement
