    17→
    18→  constructor(tokens: Token[]) {
    19→    this.tokens = tokens;
    20→  }
    21→
    22→  /**
    23→   * 메인: 토큰 스트림을 AST로 변환
    24→   */
    25→  parse(): AST.Program {
    26→    const body: AST.Statement[] = [];
    27→
    28→    while (!this.isAtEnd()) {
    29→      // EOF 전에 모든 문장 파싱
    30→      if (this.check(TokenType.EOF)) break;
    31→
    32→      // ✅ Skip NEWLINE tokens between statements (2026-03-09)
    33→      while (this.match(TokenType.NEWLINE)) {
    34→        // Skip newlines
    35→      }
    36→
    37→      if (this.isAtEnd() || this.check(TokenType.EOF)) break;
    38→
    39→      const stmt = this.parseStatement();
    40→      if (stmt) {
    41→        body.push(stmt);
    42→      }
    43→    }
    44→
    45→    return {
    46→      type: 'Program',
    47→      body,
    48→      line: 0,
    49→      column: 0,
    50→    };
    51→  }
    52→
    53→  /**
    54→   * 문장 파싱
    55→   */
    56→  private parseStatement(): AST.Statement | null {
    57→    // 빈 줄 처리: NEWLINE과 DEDENT 토큰 건너뛰기
    58→    while (this.check(TokenType.NEWLINE) || this.check(TokenType.DEDENT)) {
    59→      if (this.check(TokenType.DEDENT)) {
    60→        // DEDENT는 상위 블록에서 처리해야 함
    61→        break;
    62→      }
    63→      this.advance();
    64→    }
    65→
    66→    const token = this.peek();
    67→
    68→    if (!token || token.type === TokenType.EOF) return null;
    69→
    70→    // export 키워드 확인
    71→    let isExport = false;
    72→    if (this.check(TokenType.EXPORT)) {
    73→      isExport = true;
    74→      this.advance();
    75→    }
    76→
    77→    // 데코레이터 파싱
    78→    const decorators: AST.Decorator[] = [];
    79→    while (this.match(TokenType.AT)) {
    80→      decorators.push(this.parseDecorator());
    81→    }
    82→
    83→    // Python def 함수
    84→    if (this.check(TokenType.DEF)) {
    85→      const stmt = this.parseFunctionDef(decorators, false);
    86→      if (isExport) stmt.isExport = true;
    87→      return stmt;
    88→    }
    89→
    90→    // async def
    91→    if (this.check(TokenType.ASYNC) && this.peekAhead(1)?.type === TokenType.DEF) {
    92→      this.advance(); // async 건너뛰기
    93→      const stmt = this.parseFunctionDef(decorators, true);
    94→      if (isExport) stmt.isExport = true;
    95→      return stmt;
    96→    }
    97→
    98→    // FreeLang fn 함수
    99→    if (this.check(TokenType.FN)) {
