   103→    }
   104→
   105→    // async fn
   106→    if (this.check(TokenType.ASYNC) && this.peekAhead(1)?.type === TokenType.FN) {
   107→      this.advance();
   108→      const stmt = this.parseFreeLangFunction(decorators, true);
   109→      if (isExport) stmt.isExport = true;
   110→      return stmt;
   111→    }
