   924→  private parseComparison(): AST.Expression {
   925→    let expr = this.parseBitwiseOr();
   926→    const startLine = expr.line;
   927→    const startColumn = expr.column;
   928→
   929→    // 비교 연산자가 없으면 단순 표현식 반환
   930→    if (!this.isComparisonOp() && !this.isInOp()) {
   931→      return expr;
   932→    }
   933→
   934→    // Compare chain: a < b < c
   935→    const ops: string[] = [];
   936→    const comparators: AST.Expression[] = [];
   937→
   938→    while (this.isComparisonOp() || this.isInOp()) {
   939→      let operator: string;
   940→      if (this.check(TokenType.IN)) {
   941→        // x in list
   942→        this.advance();
   943→        operator = 'in';
   944→      } else if (this.check(TokenType.NOT)) {
   945→        // x not in list
   946→        this.advance(); // consume 'not'
   947→        this.consume(TokenType.IN, 'in 필요 (not in)');
   948→        operator = 'not in';
   949→      } else if (this.check(TokenType.IS)) {
   950→        this.advance(); // consume 'is'
   951→        if (this.check(TokenType.NOT)) {
   952→          this.advance();
   953→          operator = 'is not';
   954→        } else {
   955→          operator = 'is';
   956→        }
   957→      } else {
   958→        operator = this.advance().value;
   959→      }
   960→      ops.push(operator);
   961→      const right = this.parseBitwiseOr();
   962→      comparators.push(right);
   963→    }
   964→
   965→    // 비교가 여러 개면 Compare, 하나면 BinaryOp
   966→    if (ops.length === 1) {
   967→      return {
   968→        type: 'BinaryOp',
   969→        left: expr,
   970→        operator: ops[0],
   971→        right: comparators[0],
   972→        line: startLine,
   973→        column: startColumn,
   974→      } as AST.BinaryOp;
   975→    }
   976→
   977→    // Compare chain
   978→    return {
   979→      type: 'Compare',
   980→      expr,
   981→      ops,
   982→      comparators,
   983→      line: startLine,
   984→      column: startColumn,
   985→    } as AST.Compare;
   986→  }
