 */
private nextToken(): Token | null {
  const ch = this.peek();

  if (ch === undefined) {
    return null;
  }

  // 개행
  if (ch === '\n') {
    this.advance();
    this.atLineStart = true;
    this.column = 1;
    return this.makeToken(TokenType.NEWLINE, '\n', this.currentMode);
  }

