    const ast1 = parser1.parse();
    const codegen1 = new NexusCodegen();
    const result1 = codegen1.generate(ast1);

    expect(result1.c).toContain('long long x = 42;');

    const source2 = `@mode(python)
def test():
  x = 42`;
    const lexer2 = new NexusLexer(source2);
    const tokens2 = lexer2.tokenize();
    const parser2 = new NexusParser(tokens2);
    const ast2 = parser2.parse();
    const codegen2 = new NexusCodegen();
    const result2 = codegen2.generate(ast2);

    expect(result2.python).toContain('x = 42');
  });

  // ==================== Test 8: 전체 파이프라인 end-to-end ====================
  test('전체 파이프라인: Lexer → Parser → Codegen', () => {
    const source = `@mode(v)
fn square(x: i64) -> i64 {
  return x * x
}

@mode(python)
def double(n):
  return n + n`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const parser = new NexusParser(tokens);
    const ast = parser.parse();
    const codegen = new NexusCodegen();
    const result = codegen.generate(ast);

    // V 함수 확인
    expect(result.c).toContain('long long square(long long x)');
    expect(result.c).toContain('return x * x;');

    // Python 함수 확인
    expect(result.python).toContain('def double(n):');
    expect(result.python).toContain('return n + n');

    // mixed 필드도 둘 다 포함
    expect(result.mixed).toContain('long long square');
    expect(result.mixed).toContain('def double');
  });
});

