    expect(result1.c).toContain('long long x = 42;');

    const source2 = `@mode(python)
def test():
  x = 42`;
    const lexer2 = new NexusLexer(source2);
    const tokens2 = lexer2.tokenize();
    const parser2 = new NexusParser(tokens2);
    const ast2 = parser2.parse();
    const codegen2 = new NexusCodegen();
