/**
 * FreeLang Nexus Phase 5 - CLI + Stdlib 통합 테스트
 */

import NexusLexer from '../src/nexus/lexer/nexus-lexer';
import { NexusParser } from '../src/nexus/parser/nexus-parser';
import { NexusCodegen } from '../src/nexus/codegen/nexus-codegen';
import { NexusRunner } from '../src/nexus/runtime/nexus-runner';

describe('NexusPhase5 - CLI + Stdlib 테스트', () => {
  const codegen = new NexusCodegen();
  const runner = new NexusRunner();

  // ==================== Test 1: generateProgram() - C 헤더 ====================
  test('generateProgram(): 생성된 C에 #include <stdio.h> 포함', () => {
    const source = `@mode(v)
fn add(x: i64, y: i64) -> i64 {
  return x + y
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = codegen.generateProgram(ast);

    expect(result.c).toContain('#include <stdio.h>');
    expect(result.c).toContain('#include <stdbool.h>');
  });

  // ==================== Test 2: generateProgram() - C main() ====================
  test('generateProgram(): 생성된 C에 int main() 포함', () => {
    const source = `@mode(v)
fn square(x: i64) -> i64 {
  return x * x
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = codegen.generateProgram(ast);

    expect(result.c).toContain('int main()');
    expect(result.c).toContain('return 0;');
  });

  // ==================== Test 3: generateProgram() - Python main ====================
  test('generateProgram(): 생성된 Python에 if __name__ 포함', () => {
    const source = `@mode(python)
def hello():
  print("Hello")`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = codegen.generateProgram(ast);

    expect(result.python).toContain("if __name__ == '__main__':");
  });

  // ==================== Test 4: Stdlib 매핑 ====================
  test('기본 stdout: V 함수에서 출력 가능', () => {
    // generateProgram() → 실행 가능한 C 코드로 변환
    // 단순한 V 함수를 생성하고 main()이 자동으로 생성됨
    const source = `@mode(v)
fn test() {
  return 0
}`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = codegen.generateProgram(ast);

    // 컴파일해서 실행 가능한지 확인
    expect(result.c).toContain('int main()');
    expect(result.c).toContain('int test()');

    // 실제 컴파일하면 성공해야 함
    const runResult = runner.run(result);
    expect(runResult.errors.length).toBe(0);
  });

  // ==================== Test 5: 파이프라인 - 단순 Python 프로그램 ====================
  test('파이프라인: Python 프로그램 실행', () => {
    const source = `@mode(python)
def greet():
  print("Hello from Python")
  return 1`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = codegen.generateProgram(ast);

    // Python 코드는 함수 정의만 있고 호출이 없으므로
    // 직접 실행하면 아무 출력도 없음
    // 이는 의도적 (함수 정의만 생성)

    expect(result.python).toContain('def greet():');
    expect(result.python).toContain('print("Hello from Python")');
  });

  // ==================== Test 6: 혼합 모드 - 전체 파이프라인 ====================
  test('혼합 모드: V + Python 코드 실행', () => {
    const source = `@mode(v)
fn value() {
  return 42
}

@mode(python)
def compute():
  return value() * 2`;
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();
    const ast = new NexusParser(tokens).parse();
    const result = codegen.generateProgram(ast);

    // C 코드가 생성됨 (main 포함)
    expect(result.c).toContain('int main()');
    expect(result.c).toContain('int value()');

    // Python 코드도 생성됨
    expect(result.python).toContain('def compute():');

    // 런너가 각각 실행 (에러 없음)
    const runResult = runner.run(result);
    expect(runResult.errors.length).toBe(0);
  });
});

