     1→#!/usr/bin/env node
     2→
     3→/**
     4→ * FreeLang Nexus CLI
     5→ * Usage:
     6→ *   nexus run <file>      - 파일 실행
     7→ *   nexus compile <file>  - 코드 생성만 (컴파일/실행 안함)
     8→ *   nexus check <file>    - 문법 검사만
     9→ */
    10→
    11→import * as fs from 'fs';
    12→import * as path from 'path';
    13→import NexusLexer from './lexer/nexus-lexer';
    14→import { NexusParser } from './parser/nexus-parser';
    15→import { NexusCodegen } from './codegen/nexus-codegen';
    16→import { NexusRunner } from './runtime/nexus-runner';
    17→
    18→function printUsage() {
    19→  console.log(`
    20→FreeLang Nexus CLI
    21→
    22→Usage:
    23→  nexus run <file>      실행: .fl 파일 실행
    24→  nexus compile <file>  컴파일: C/Python 코드만 출력
    25→  nexus check <file>    검사: 문법 검사만
    26→  nexus --version       버전 표시
    27→  nexus --help          도움말
    28→
    29→Examples:
    30→  nexus run hello.fl
    31→  nexus compile hello.fl
    32→  nexus check hello.fl
    33→`);
    34→}
    35→
    36→async function runFile(filePath: string): Promise<void> {
    37→  try {
    38→    // 파일 읽기
    39→    if (!fs.existsSync(filePath)) {
    40→      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
    41→      process.exit(1);
    42→    }
    43→
    44→    const source = fs.readFileSync(filePath, 'utf-8');
    45→
    46→    // Lexer
    47→    const lexer = new NexusLexer(source);
    48→    const tokens = lexer.tokenize();
    49→
    50→    // Parser
    51→    const parser = new NexusParser(tokens);
    52→    const ast = parser.parse();
    53→
    54→    // CodeGen
    55→    const codegen = new NexusCodegen();
    56→    const result = codegen.generateProgram(ast);
    57→
    58→    // Runner
    59→    const runner = new NexusRunner();
    60→    const runResult = runner.run(result);
    61→
    62→    // 결과 출력
    63→    if (runResult.cOutput) {
    64→      console.log(runResult.cOutput);
    65→    }
    66→    if (runResult.pythonOutput) {
    67→      console.log(runResult.pythonOutput);
    68→    }
    69→
    70→    // 에러 출력
    71→    if (runResult.errors.length > 0) {
    72→      console.error('❌ 에러:');
    73→      runResult.errors.forEach((e) => console.error(`  ${e}`));
    74→      process.exit(1);
    75→    }
    76→  } catch (e) {
    77→    console.error(`❌ 오류: ${(e as Error).message}`);
    78→    process.exit(1);
    79→  }
    80→}
    81→
    82→async function compileFile(filePath: string): Promise<void> {
    83→  try {
    84→    if (!fs.existsSync(filePath)) {
    85→      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
    86→      process.exit(1);
    87→    }
    88→
    89→    const source = fs.readFileSync(filePath, 'utf-8');
    90→
    91→    // Lexer
    92→    const lexer = new NexusLexer(source);
    93→    const tokens = lexer.tokenize();
    94→
    95→    // Parser
    96→    const parser = new NexusParser(tokens);
    97→    const ast = parser.parse();
    98→
    99→    // CodeGen
   100→    const codegen = new NexusCodegen();
   101→    const result = codegen.generateProgram(ast);
   102→
   103→    // C 코드 출력
   104→    if (result.c) {
   105→      console.log('/* === C Code ===*/');
   106→      console.log(result.c);
   107→    }
   108→
   109→    // Python 코드 출력
   110→    if (result.python) {
   111→      if (result.c) {
   112→        console.log('\n# === Python Code ===');
   113→      }
   114→      console.log(result.python);
   115→    }
   116→
   117→    if (!result.c && !result.python) {
   118→      console.log('// (No code generated)');
   119→    }
   120→  } catch (e) {
   121→    console.error(`❌ 오류: ${(e as Error).message}`);
   122→    process.exit(1);
   123→  }
   124→}
   125→
   126→async function checkFile(filePath: string): Promise<void> {
   127→  try {
   128→    if (!fs.existsSync(filePath)) {
   129→      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
   130→      process.exit(1);
   131→    }
   132→
   133→    const source = fs.readFileSync(filePath, 'utf-8');
   134→
   135→    // Lexer
   136→    const lexer = new NexusLexer(source);
   137→    const tokens = lexer.tokenize();
   138→
   139→    // Parser
   140→    const parser = new NexusParser(tokens);
   141→    const ast = parser.parse();
   142→
   143→    console.log('✅ 문법 검사 통과');
   144→    console.log(`   함수: ${ast.body.filter((b: any) => b.type === 'VFunction' || b.type === 'PyFunction').length}개`);
   145→  } catch (e) {
   146→    console.error(`❌ 오류: ${(e as Error).message}`);
   147→    process.exit(1);
   148→  }
   149→}
   150→
   151→async function main() {
   152→  const args = process.argv.slice(2);
   153→
   154→  if (args.length === 0) {
   155→    printUsage();
   156→    process.exit(0);
   157→  }
   158→
   159→  const cmd = args[0];
   160→  const file = args[1];
   161→
   162→  if (cmd === '--help' || cmd === '-h') {
   163→    printUsage();
   164→  } else if (cmd === '--version' || cmd === '-v') {
   165→    console.log('FreeLang Nexus 1.0.0');
   166→  } else if (cmd === 'run') {
   167→    if (!file) {
   168→      console.error('❌ 파일 경로 필요: nexus run <file>');
   169→      process.exit(1);
   170→    }
   171→    await runFile(file);
   172→  } else if (cmd === 'compile') {
   173→    if (!file) {
   174→      console.error('❌ 파일 경로 필요: nexus compile <file>');
   175→      process.exit(1);
   176→    }
   177→    await compileFile(file);
   178→  } else if (cmd === 'check') {
   179→    if (!file) {
   180→      console.error('❌ 파일 경로 필요: nexus check <file>');
   181→      process.exit(1);
   182→    }
   183→    await checkFile(file);
   184→  } else {
   185→    console.error(`❌ 알 수 없는 커맨드: ${cmd}`);
   186→    printUsage();
   187→    process.exit(1);
   188→  }
   189→}
   190→
   191→main();
