| `src/nexus/repl/nexus-repl.ts` | **신규**: REPL 클래스 | ~110줄 |
| `src/nexus/index.ts` | **수정**: `repl` 서브커맨드 추가 | +10줄 |
| `tests/nexus-phase6.test.ts` | **신규**: 단위 테스트 6개 | ~80줄 |

---

## Step 1: REPL 클래스 (`src/nexus/repl/nexus-repl.ts` 신규)

핵심 설계:
- `eval(input): string` → readline 없이 호출 가능 → **단위 테스트 가능**
- `handleCommand(cmd): string` → REPL 메타 커맨드 처리
- `start(): void` → readline 루프 (CLI 진입)
- 멀티라인: `:` 로 끝나거나 버퍼에 내용이 있으면 계속 입력 대기, 빈 줄 입력으로 제출

```typescript
import * as readline from 'readline';
import NexusLexer from '../lexer/nexus-lexer';
import { NexusParser } from '../parser/nexus-parser';
import { NexusCodegen } from '../codegen/nexus-codegen';
import { NexusRunner } from '../runtime/nexus-runner';

const HELP_TEXT = `FreeLang Nexus REPL 커맨드:
  /mode v        V 모드로 전환 (기본)
  /mode python   Python 모드로 전환
  /mode          현재 모드 확인
  /help          이 도움말
  /exit          종료`;

export class NexusRepl {
  private mode: 'v' | 'python' = 'v';
  private runner = new NexusRunner();
  private buffer: string[] = [];

  eval(input: string): string {
    if (input.startsWith('/')) return this.handleCommand(input.trim());
    const source = `@mode(${this.mode})\n${input}`;
    try {
      const tokens = new NexusLexer(source).tokenize();
      const ast = new NexusParser(tokens).parse();
      const result = new NexusCodegen().generateProgram(ast);
      const runResult = this.runner.run(result);
      if (runResult.errors.length > 0) return `❌ ${runResult.errors.join('\n')}`;
      const out = [runResult.cOutput, runResult.pythonOutput].filter(Boolean).join('\n').trim();
      return out || '(no output)';
    } catch (e) {
      return `❌ ${(e as Error).message}`;
    }
  }

  handleCommand(cmd: string): string {
    if (cmd === '/mode v') { this.mode = 'v'; return '모드: V'; }
    if (cmd === '/mode python') { this.mode = 'python'; return '모드: Python'; }
    if (cmd === '/mode') return `현재 모드: ${this.mode}`;
    if (cmd === '/help') return HELP_TEXT;
    return `알 수 없는 커맨드: ${cmd}. /help 참고`;
  }

  getMode(): string { return this.mode; }

  start(): void {
    console.log('FreeLang Nexus REPL v1.0.0  (/help 도움말  /exit 종료)');
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    const prompt = () => this.buffer.length > 0 ? '...   ' : `${this.mode}> `;
    const ask = () => {
      rl.question(prompt(), (line) => {
        if (line === '/exit' || line === '.exit') { rl.close(); return; }
        // 멀티라인 감지
        if (line.endsWith(':')) { this.buffer.push(line); return ask(); }
        if (this.buffer.length > 0 && line.trim() !== '') { this.buffer.push(line); return ask(); }
        const full = this.buffer.length > 0 ? [...this.buffer, line].join('\n') : line;
        this.buffer = [];
        if (full.trim()) { const out = this.eval(full); console.log(out); }
        ask();
      });
    };
    ask();
  }
}
```

