 */

import * as readline from 'readline';
import NexusLexer from '../lexer/nexus-lexer';
import { NexusParser } from '../parser/nexus-parser';
import { NexusCodegen } from '../codegen/nexus-codegen';
import { NexusRunner } from '../runtime/nexus-runner';

const HELP_TEXT = `FreeLang Nexus REPL 커맨드:
  /mode v        V 모드로 전환 (기본)
  /mode python   Python 모드로 전환
  /mode          현재 모드 확인
  /help          이 도움말
  /exit          종료`;

export class NexusRepl {
  private mode: 'v' | 'python' = 'v';
  private runner = new NexusRunner();
  private buffer: string[] = [];

  /**
   * 입력 한 줄 평가
   * readline 없이 호출 가능 → 단위 테스트 가능
   */
  eval(input: string): string {
    // 커맨드 처리
    if (input.startsWith('/')) {
      return this.handleCommand(input.trim());
    }

    // @mode(v) 또는 @mode(python) 자동 삽입 후 파이프라인 실행
    const source = `@mode(${this.mode})\n${input}`;

    try {
      const tokens = new NexusLexer(source).tokenize();
      const ast = new NexusParser(tokens).parse();
      const result = new NexusCodegen().generateProgram(ast);
      const runResult = this.runner.run(result);

      // 에러 확인
      if (runResult.errors.length > 0) {
        return `❌ ${runResult.errors.join('\n')}`;
      }

      // 출력 결합
      const out = [runResult.cOutput, runResult.pythonOutput]
        .filter(Boolean)
        .join('\n')
        .trim();

      return out || '(no output)';
    } catch (e) {
      return `❌ ${(e as Error).message}`;
    }
  }

  /**
   * REPL 메타 커맨드 처리
   */
  handleCommand(cmd: string): string {
    if (cmd === '/mode v') {
      this.mode = 'v';
      return '모드: V';
    }
    if (cmd === '/mode python') {
      this.mode = 'python';
      return '모드: Python';
    }
    if (cmd === '/mode') {
      return `현재 모드: ${this.mode}`;
    }
    if (cmd === '/help') {
      return HELP_TEXT;
    }
    return `알 수 없는 커맨드: ${cmd}. /help 참고`;
  }

  /**
   * 현재 모드 반환 (테스트용)
   */
  getMode(): string {
    return this.mode;
  }

  /**
   * REPL 시작 (readline 루프)
   */
  start(): void {
    console.log('FreeLang Nexus REPL v1.0.0  (/help 도움말  /exit 종료)');

    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
    });

    const getPrompt = () => (this.buffer.length > 0 ? '...   ' : `${this.mode}> `);

    const ask = () => {
      rl.question(getPrompt(), (line) => {
        // 종료
        if (line === '/exit' || line === '.exit') {
          rl.close();
          return;
        }

        // 멀티라인 감지: ':' 로 끝나면 계속 입력
        if (line.endsWith(':')) {
          this.buffer.push(line);
          return ask();
        }

        // 버퍼에 내용이 있고, 입력도 있으면 계속 모으기
        if (this.buffer.length > 0 && line.trim() !== '') {
          this.buffer.push(line);
          return ask();
        }

        // 제출: 버퍼 + 현재 줄 합쳐서 실행
        const full = this.buffer.length > 0 ? [...this.buffer, line].join('\n') : line;
        this.buffer = [];

        if (full.trim()) {
          const out = this.eval(full);
          console.log(out);
        }

        ask();
      });
    };

    ask();
  }
}

