#!/usr/bin/env node

/**
 * FreeLang Nexus CLI
 * Usage:
 *   nexus run <file>      - 파일 실행
 *   nexus compile <file>  - 코드 생성만 (컴파일/실행 안함)
 *   nexus check <file>    - 문법 검사만
 */

import * as fs from 'fs';
import * as path from 'path';
import NexusLexer from './lexer/nexus-lexer';
import { NexusParser } from './parser/nexus-parser';
import { NexusCodegen } from './codegen/nexus-codegen';
import { NexusRunner } from './runtime/nexus-runner';

function printUsage() {
  console.log(`
FreeLang Nexus CLI

Usage:
  nexus run <file>      실행: .fl 파일 실행
  nexus compile <file>  컴파일: C/Python 코드만 출력
  nexus check <file>    검사: 문법 검사만
  nexus --version       버전 표시
  nexus --help          도움말

Examples:
  nexus run hello.fl
  nexus compile hello.fl
  nexus check hello.fl
`);
}

async function runFile(filePath: string): Promise<void> {
  try {
    // 파일 읽기
    if (!fs.existsSync(filePath)) {
      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
      process.exit(1);
    }

    const source = fs.readFileSync(filePath, 'utf-8');

    // Lexer
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // Parser
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    // CodeGen
    const codegen = new NexusCodegen();
    const result = codegen.generateProgram(ast);

    // Runner
    const runner = new NexusRunner();
    const runResult = runner.run(result);

    // 결과 출력
    if (runResult.cOutput) {
      console.log(runResult.cOutput);
    }
    if (runResult.pythonOutput) {
      console.log(runResult.pythonOutput);
    }

    // 에러 출력
    if (runResult.errors.length > 0) {
      console.error('❌ 에러:');
      runResult.errors.forEach((e) => console.error(`  ${e}`));
      process.exit(1);
    }
  } catch (e) {
    console.error(`❌ 오류: ${(e as Error).message}`);
    process.exit(1);
  }
}

async function compileFile(filePath: string): Promise<void> {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
      process.exit(1);
    }

    const source = fs.readFileSync(filePath, 'utf-8');

    // Lexer
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // Parser
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    // CodeGen
    const codegen = new NexusCodegen();
    const result = codegen.generateProgram(ast);

    // C 코드 출력
    if (result.c) {
      console.log('/* === C Code ===*/');
      console.log(result.c);
    }

    // Python 코드 출력
    if (result.python) {
      if (result.c) {
        console.log('\n# === Python Code ===');
      }
      console.log(result.python);
    }

    if (!result.c && !result.python) {
      console.log('// (No code generated)');
    }
  } catch (e) {
    console.error(`❌ 오류: ${(e as Error).message}`);
    process.exit(1);
  }
}

async function checkFile(filePath: string): Promise<void> {
  try {
    if (!fs.existsSync(filePath)) {
      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
      process.exit(1);
    }

    const source = fs.readFileSync(filePath, 'utf-8');

    // Lexer
    const lexer = new NexusLexer(source);
    const tokens = lexer.tokenize();

    // Parser
    const parser = new NexusParser(tokens);
    const ast = parser.parse();

    console.log('✅ 문법 검사 통과');
    console.log(`   함수: ${ast.body.filter((b: any) => b.type === 'VFunction' || b.type === 'PyFunction').length}개`);
  } catch (e) {
    console.error(`❌ 오류: ${(e as Error).message}`);
    process.exit(1);
  }
}

async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    printUsage();
